bool searchMatrix(auto matrix, auto target) {
  if (!matrix.size()) return false;
  const auto rows = matrix.size(), cols = matrix[0].size();
  auto low = 0, high = rows * cols - 1;
  while (low <= high) {
    const auto mid = ((low + high) / 2);
    const auto r = (mid / cols), c = mid % cols;
    if (matrix[r][c] == target) return true;
    if (matrix[r][c] < target) low = mid + 1;
    else high = mid - 1;
  }
  return false;
}

