auto myPow(auto x, auto n) {
  if (n == 0) return 1.0;
  auto nn = n < 0 ? -n : n;
  auto ans = 1.0;
  while (nn > 0) {
    if (nn % 2 == 1) {
      ans = ans * x;
      nn = nn - 1;
    } else {
      x = x * x;
      nn = nn / 2;
    }
  }
  return n < 0 ? 1.0 / ans : ans;
}

