auto reversePairs(auto nums) {
  auto mergeSort(auto left, auto right) {
    if (left >= right) return 0;
    const auto mid = ((left + right) / 2);
    auto count = mergeSort(left, mid) + mergeSort(mid + 1, right);
    auto j = mid + 1;
    for (auto i = left; i <= mid; i++) {
      while (j <= right && nums[i] > 2 * nums[j]) j++;
      count += (j - (mid + 1));
    }
    merge(left, mid, right);
    return count;
  }
  auto merge(auto left, auto mid, auto right) {
    const auto temp = [];
    auto i = left, j = mid + 1;
    while (i <= mid && j <= right) {
      if (nums[i] <= nums[j]) temp.push(nums[i++]);
      else temp.push(nums[j++]);
    }
    while (i <= mid) temp.push(nums[i++]);
    while (j <= right) temp.push(nums[j++]);
    for (auto x = left; x <= right; x++) nums[x] = temp[x - left];
  }
  return mergeSort(0, nums.size() - 1);
}

