auto solve(auto A, auto B) {
  const auto map = unordered_map<int, int>();
  map.set(0, 1);
  auto xor = 0, count = 0;
  for (auto i = 0; i < A.size(); i++) {
    xor = xor ^ A[i];
    const auto x = xor ^ B;
    if (map.has(x)) {
