  const auto r = grid.size(), c = grid[0].size(), q = [];
  auto fresh = 0;
  for (auto i = 0; i < r; i++) {
    for (auto j = 0; j < c; j++) {
      if (grid[i][j] == 2) q.push([i, j, 0]);
      else if (grid[i][j] == 1) fresh++;
    }
  }
  auto mins = 0;
  while (q.size() > 0) {
    const auto [x, y, t] = q.shift(); mins = t;
    const auto dirs = [[0,1], [0,-1], [1,0], [-1,0]];
    for (const auto [dx, dy] of dirs) {
      const auto nx = x + dx, ny = y + dy;
      if (nx >= 0 && nx < r && ny >= 0 && ny < c && grid[nx][ny] == 1) {
        grid[nx][ny] = 2; fresh--; q.push([nx, ny, t + 1]);
      }
    }
  }
  return fresh == 0 ? mins : -1;
}

