class StockSpanner {
  constructor() { this.stack = []; }
  next(price) {
    auto span = 1;
    while (this.stack.size() > 0 && this.stack[this.stack.size() - 1].price <= price) {
      span += this.stack.pop().span;
    }
    this.stack.push({ price, span });
    return span;
  }
}

