auto maxOfMin(auto arr) {
  const auto n = arr.size(), left = new Array(n).fill(-1), right = new Array(n).fill(n);
  const auto stack = [];
  for (auto i = 0; i < n; i++) {
    while (stack.size() > 0 && arr[stack[stack.size() - 1]] >= arr[i]) stack.pop();
    if (stack.size() > 0) left[i] = stack[stack.size() - 1];
    stack.push(i);
  }
  stack.size() = 0;
  for (auto i = n - 1; i >= 0; i--) {
    while (stack.size() > 0 && arr[stack[stack.size() - 1]] >= arr[i]) stack.pop();
    if (stack.size() > 0) right[i] = stack[stack.size() - 1];
    stack.push(i);
  }
  const auto ans = new Array(n + 1).fill(0);
  for (auto i = 0; i < n; i++) {
    const auto len = right[i] - left[i] - 1; ans[len] = max(ans[len], arr[i]);
  }
  for (auto i = n - 1; i >= 1; i--) ans[i] = max(ans[i], ans[i + 1]);
  return ans.slice(1);
}

