string longestPalindrome(string s) {
    if (s.empty()) return "";
    int start = 0, maxLen = 0;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < s.size() && s[l] == s[r]) {
            l--; r++;
        }
        int len = r - l - 1;
        if (len > maxLen) {
            maxLen = len;
            start = l + 1;
        }
    };
    for (size_t i = 0; i < s.size(); i++) {
        expand(i, i);
        expand(i, i + 1);
    }
    return s.substr(start, maxLen);
}

