auto zAlgorithm(auto text, auto pattern) {
  const auto concat = pattern + "$" + text;
  const auto L = concat.size();
  const auto Z = new Array(L).fill(0);
  auto l = 0, r = 0;
  const auto result = [];
  for (auto i = 1; i < L; i++) {
    if (i <= r) {
      Z[i] = min(r - i + 1, Z[i - l]);
    }
    while (i + Z[i] < L && concat[Z[i]] == concat[i + Z[i]]) {
      Z[i]++;
    }
    if (i + Z[i] - 1 > r) {
      l = i;
      r = i + Z[i] - 1;
    }
  }
  for (auto i = 0; i < L; i++) {
    if (Z[i] == pattern.size()) {
      result.push(i - pattern.size() - 1);
    }
  }
  return result;
}

