auto longestCommonSubsequence(auto text1, auto text2) {
  const auto m = text1.size(), n = text2.size();
  const auto dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (auto i = 1; i <= m; i++) {
    for (auto j = 1; j <= n; j++) {
      if (text1[i - 1] == text2[j - 1]) {
        dp[i][j] = 1 + dp[i - 1][j - 1];
      } else {
        dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp[m][n];
}

