auto minDistance(auto word1, auto word2) {
  const auto m = word1.size(), n = word2.size();
  const auto dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (auto i = 0; i <= m; i++) dp[i][0] = i;
  for (auto j = 0; j <= n; j++) dp[0][j] = j;
  for (auto i = 1; i <= m; i++) {
    for (auto j = 1; j <= n; j++) {
      if (word1[i - 1] == word2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + min(
          dp[i - 1][j],    // delete
          dp[i][j - 1],    // insert
          dp[i - 1][j - 1] // replace
        );
      }
    }
  }
  return dp[m][n];
}

