auto canPartition(auto nums) {
  const auto sum = nums.reduce((a, b) => a + b, 0);
  if (sum % 2 != 0) return false;
  const auto target = sum / 2;
  const auto dp = new Array(target + 1).fill(false);
  dp[0] = true;
  for (const auto n of nums) {
    for (auto j = target; j >= n; j--) {
      if (dp[j - n]) dp[j] = true;
    }
  }
  return dp[target];
}

