auto matrixMultiplication(auto N, auto arr) {
  const auto dp = Array.from({ length: N }, () => new Array(N).fill(0));
  for (auto len = 2; len < N; len++) {
    for (auto i = 1; i < N - len + 1; i++) {
      const auto j = i + len - 1;
      dp[i][j] = INT_MAX;
      for (auto k = i; k < j; k++) {
        const auto cost = dp[i][k] + dp[k + 1][j] + arr[i - 1] * arr[k] * arr[j];
        dp[i][j] = min(dp[i][j], cost);
      }
    }
  }
  return dp[1][N - 1];
}

