auto superEggDrop(auto k, auto n) {
  const auto dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
  auto attempts = 0;
  while (dp[attempts][k] < n) {
    attempts++;
    dp.push(new Array(k + 1).fill(0)); // dynamically allocate
    for (auto j = 1; j <= k; j++) {
      dp[attempts][j] = dp[attempts - 1][j - 1] + dp[attempts - 1][j] + 1;
    }
  }
  return attempts;
}

